INSERT INTO studio_posts (id, title, slug, excerpt, cover_image, body, category, tags, status, published_at, scheduled_at, created_at, updated_at, seo_title, seo_description, external_media, github_commit_sha, last_publish_error)
VALUES ('post-1', 'Rebuilding EmmaKwon.com with AI', 'rebuilding-emmakwon-with-ai', 'This site has gone through more rebuilds than I''d like to admit. Here''s what it actually looks like to design in the browser with an AI that never gets tired of your notes.', NULL, '["I didn''t design this site once and ship it. I designed it maybe thirty times, in small pieces, over weeks — a hero that felt too tall, a header that drifted too far right, a background that looked like a pinwheel instead of an atmosphere.","The process that worked was small, specific corrections. Not ''make it better'' — that never works. ''The video feels like a giant poster, restore the version where it breathes.'' ''The gold hover feels cheap, use the pink from the hair.'' Precise notes, one change at a time.","The AI is fast. It is not tasteful on its own. Taste is still the part I have to bring — I just get to see it rendered in minutes instead of days."]', 'BUILD', '["ai workflow","web design","claude code"]', 'published', '2026-08-10T09:00:00+10:00', NULL, '2026-08-07T18:20:00+10:00', '2026-08-10T09:00:00+10:00', 'Rebuilding EmmaKwon.com with AI', 'A behind-the-scenes look at rebuilding this site in small, precise corrections with an AI coding assistant.', NULL, NULL, NULL)
