INSERT INTO studio_posts (id, title, slug, excerpt, cover_image, body, category, tags, status, published_at, scheduled_at, created_at, updated_at, seo_title, seo_description, external_media, github_commit_sha, last_publish_error)
VALUES ('post-2', 'Making (and Remaking) the Favicon', 'making-the-favicon', 'A tiny 32-pixel icon took five separate rounds to get right. What that taught me about restraint.', NULL, '["I asked for a monogram. Then a star. Then a full aurora gradient circle. Then I looked at it next to the header and it felt loud, so I stripped it back to a plain navy E.","Then I missed the circle. The final version keeps the circular badge and the aurora gradient, just with the E sized up slightly so it holds its own inside the badge.","Small things get to be iterated on exactly like big things. Nobody sees the four versions that didn''t make it — they just see the tab."]', 'BUILD', '["branding","iteration","favicon"]', 'published', '2026-08-03T09:00:00+10:00', NULL, '2026-08-01T14:10:00+10:00', '2026-08-03T09:00:00+10:00', 'Making (and Remaking) the Favicon', 'Five rounds of iteration on a 32-pixel favicon, and what it taught me about restraint.', NULL, NULL, NULL)
