INSERT INTO studio_posts (id, title, slug, excerpt, cover_image, body, category, tags, status, published_at, scheduled_at, created_at, updated_at, seo_title, seo_description, external_media, github_commit_sha, last_publish_error)
VALUES ('post-3', 'Using NotebookLM After English Class', 'notebooklm-after-english-class', 'My class notes are messy. Reorganizing them with NotebookLM turned an hour of class into something I can actually study from.', NULL, '["Language school moves fast. I write down phrases as I hear them, half in English, half in shorthand only I understand.","After class, I feed the messy notes into NotebookLM and ask it to organize them by topic instead of by the order I heard them in. That''s it — no rewriting, no simplifying, just reorganizing.","It''s not a study app. It''s just a second pass at my own notes, done in minutes instead of never."]', 'BUILD', '["notebooklm","workflow","english learning"]', 'published', '2026-07-27T09:00:00+10:00', NULL, '2026-07-25T20:05:00+10:00', '2026-07-27T09:00:00+10:00', 'Using NotebookLM After English Class', 'How I turn messy language-school notes into study material with NotebookLM.', NULL, NULL, NULL)
