INSERT INTO studio_posts (id, title, slug, excerpt, cover_image, body, category, tags, status, published_at, scheduled_at, created_at, updated_at, seo_title, seo_description, external_media, github_commit_sha, last_publish_error)
VALUES ('post-4', 'English I''m Learning in Brisbane', 'english-im-learning-in-brisbane', 'I''m not a teacher. I''m a student writing down what I''m learning so I understand it better — and maybe it helps you too.', NULL, '["I got on the AI wave at 50. Around the same time, I started English classes in Brisbane, which turned out to be its own kind of steep learning curve.","This isn''t a course. I''m not qualified to teach anyone English. What I am doing is writing down the phrases, mistakes, and small breakthroughs from class each week, mostly so I remember them.","If a note here happens to help someone else learning English, that''s a nice side effect — not the point."]', 'LEARN', '["english learning","brisbane","language school"]', 'published', '2026-07-20T09:00:00+10:00', NULL, '2026-07-18T19:30:00+10:00', '2026-07-20T09:00:00+10:00', 'English I''m Learning in Brisbane', 'Notes from language school in Brisbane, written down as I learn, not as a teacher.', '[{"label":"Watch on YouTube","url":"#"}]', NULL, NULL)
